const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{
        .name = "kvhttp",
        .root_module = root_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Serves a single HTTP/1.1 request on an accepted connection, then closes it.

const Connection = @This();

const std = @import("std");
const Io = std.Io;
const http = std.http;
const net = Io.net;
const Allocator = std.mem.Allocator;

const Store = @import("Store.zig");
const route = @import("route.zig");

const log = std.log.scoped(.connection);

/// Largest accepted value, in bytes.
pub const max_value_len = 1 << 20;
/// Largest accepted request head, in bytes.
const max_head_len = 16 * 1024;

const text_plain: http.Header = .{ .name = "content-type", .value = "text/plain; charset=utf-8" };
const application_json: http.Header = .{ .name = "content-type", .value = "application/json" };

store: *Store,
io: Io,
gpa: Allocator,

/// Entry point for a connection task. Never fails: errors only affect this
/// connection and are logged.
pub fn handle(store: *Store, io: Io, gpa: Allocator, stream: net.Stream) void {
    defer stream.close(io);

    var recv_buffer: [max_head_len]u8 = undefined;
    var send_buffer: [8 * 1024]u8 = undefined;
    var stream_reader = stream.reader(io, &recv_buffer);
    var stream_writer = stream.writer(io, &send_buffer);
    var server: http.Server = .init(&stream_reader.interface, &stream_writer.interface);

    const c: Connection = .{ .store = store, .io = io, .gpa = gpa };
    c.serve(&server) catch |err| switch (err) {
        error.ReadFailed => log.debug("read failed: {t}", .{stream_reader.err orelse err}),
        error.WriteFailed => log.debug("write failed: {t}", .{stream_writer.err orelse err}),
        else => log.debug("connection dropped: {t}", .{err}),
    };
}

const ServeError = error{
    ReadFailed,
    WriteFailed,
    EndOfStream,
    HttpRequestTruncated,
    HttpExpectationFailed,
} || Io.Cancelable;

fn serve(c: Connection, server: *http.Server) ServeError!void {
    const head_bytes = server.reader.receiveHead() catch |err| switch (err) {
        error.HttpConnectionClosing => return,
        error.HttpHeadersOversize => return respondBare(server.out, .request_header_fields_too_large),
        error.HttpRequestTruncated, error.ReadFailed => |e| return e,
    };
    const head = http.Server.Request.Head.parse(head_bytes) catch |err| switch (err) {
        // std.http only knows the standard methods; any other token is still
        // a valid request, just one no route supports.
        error.UnknownHttpMethod => return respondBare(server.out, unknownMethodStatus(head_bytes)),
        else => return respondBare(server.out, .bad_request),
    };
    var request: http.Server.Request = .{ .server = server, .head = head, .head_buffer = head_bytes };

    c.dispatch(&request) catch |err| switch (err) {
        error.OutOfMemory => {
            log.warn("out of memory serving a {t} request", .{head.method});
            return respond(&request, .internal_server_error, "", null);
        },
        else => |e| return e,
    };
}

fn dispatch(c: Connection, request: *http.Server.Request) (ServeError || Allocator.Error)!void {
    switch (route.resolve(request.head.method, request.head.target)) {
        .health => try respond(request, .ok, "ok", text_plain),
        .list_keys => {
            const json = try c.store.keysJson(c.io, c.gpa);
            defer c.gpa.free(json);
            try respond(request, .ok, json, application_json);
        },
        .get_value => |key| {
            const value = try c.store.get(c.io, c.gpa, key) orelse
                return respond(request, .not_found, "", null);
            defer c.gpa.free(value);
            try respond(request, .ok, value, null);
        },
        .put_value => |key| try c.put(request, key),
        .delete_value => |key| {
            const removed = try c.store.remove(c.io, key);
            try respond(request, if (removed) .no_content else .not_found, "", null);
        },
        .status => |status| try respond(request, status, "", null),
    }
}

fn put(c: Connection, request: *http.Server.Request, key_in_head: []const u8) (ServeError || Allocator.Error)!void {
    // Reading the body may overwrite the head buffer the key points into.
    var key_buffer: [route.max_key_len]u8 = undefined;
    const key = key_buffer[0..key_in_head.len];
    @memcpy(key, key_in_head);

    const value = readValue(request, c.gpa) catch |err| switch (err) {
        error.ValueTooLarge => return respondStatusOnly(request, .payload_too_large),
        else => |e| return e,
    };
    const result = c.store.put(c.io, key, value) catch |err| {
        c.gpa.free(value);
        return err;
    };
    try respondStatusOnly(request, switch (result) {
        .created => .created,
        .replaced => .ok,
    });
}

/// Reads the request body into memory allocated with `gpa`.
fn readValue(request: *http.Server.Request, gpa: Allocator) (ServeError || Allocator.Error || error{ValueTooLarge})![]u8 {
    const head = request.head;
    // A request with neither Content-Length nor Transfer-Encoding has no body.
    if (head.transfer_encoding == .none and head.content_length == null) return gpa.alloc(u8, 0);
    if (head.content_length) |len| if (len > max_value_len) return error.ValueTooLarge;

    var transfer_buffer: [4096]u8 = undefined;
    const body = try request.readerExpectContinue(&transfer_buffer);
    if (head.content_length) |len| {
        const value = try gpa.alloc(u8, @intCast(len));
        errdefer gpa.free(value);
        try body.readSliceAll(value);
        return value;
    }
    return body.allocRemaining(gpa, .limited(max_value_len + 1)) catch |err| switch (err) {
        error.StreamTooLong => error.ValueTooLarge,
        else => |e| e,
    };
}

/// Responds to a request whose body has already been consumed or must not be.
fn respondStatusOnly(request: *http.Server.Request, status: http.Status) ServeError!void {
    try request.respond("", .{
        .status = status,
        .keep_alive = false,
        .transfer_encoding = if (status == .no_content) .none else null,
    });
}

/// Drains any request body, then sends a complete response and closes the
/// connection. Draining first avoids the kernel resetting the connection
/// because of unread input when the socket is closed.
fn respond(
    request: *http.Server.Request,
    status: http.Status,
    content: []const u8,
    content_type: ?http.Header,
) ServeError!void {
    try discardBody(request);
    try request.respond(content, .{
        .status = status,
        .keep_alive = false,
        // A 204 response must not carry Content-Length; the connection close
        // delimits it instead.
        .transfer_encoding = if (status == .no_content) .none else null,
        .extra_headers = if (content_type) |h| &.{h} else &.{},
    });
}

/// Discards a request body that the route does not use. Bodies larger than
/// any value we accept are left unread; the connection closes either way.
fn discardBody(request: *http.Server.Request) ServeError!void {
    const head = &request.head;
    // The client waits for "100 Continue" before sending; it never will be.
    if (head.expect != null) return;
    const len = head.content_length orelse return;
    if (len == 0 or len > max_value_len) return;
    try request.server.reader.in.discardAll(@intCast(len));
    // Header strings may have been overwritten by the discarded bytes.
    head.content_type = null;
}

/// Response for a request line whose method `std.http` does not recognise.
fn unknownMethodStatus(head_bytes: []const u8) http.Status {
    const line_end = std.mem.find(u8, head_bytes, "\r\n") orelse head_bytes.len;
    var it = std.mem.tokenizeScalar(u8, head_bytes[0..line_end], ' ');
    _ = it.next(); // method
    const target = it.next() orelse return .bad_request;
    return switch (route.resolve(null, target)) {
        .status => |status| status,
        else => unreachable, // every route requires a known method
    };
}

/// Writes a minimal response when no parsed `Request` is available.
fn respondBare(out: *Io.Writer, status: http.Status) ServeError!void {
    try out.print("HTTP/1.1 {d} {s}\r\nconnection: close\r\ncontent-length: 0\r\n\r\n", .{
        @intFromEnum(status), status.phrase() orelse "",
    });
    try out.flush();
}

test unknownMethodStatus {
    const testing = std.testing;
    try testing.expectEqual(http.Status.method_not_allowed, unknownMethodStatus("FOO /health HTTP/1.1\r\n\r\n"));
    try testing.expectEqual(http.Status.method_not_allowed, unknownMethodStatus("FOO /kv/a HTTP/1.1\r\n\r\n"));
    try testing.expectEqual(http.Status.bad_request, unknownMethodStatus("FOO /kv/a.b HTTP/1.1\r\n\r\n"));
    try testing.expectEqual(http.Status.not_found, unknownMethodStatus("FOO /x HTTP/1.1\r\n\r\n"));
    try testing.expectEqual(http.Status.bad_request, unknownMethodStatus("FOO\r\n\r\n"));
}

//! Thread-safe in-memory key-value store.
//!
//! Keys and values are owned by the store and allocated with `gpa`.
//! Readers receive copies so that no lock is held while a response is written.

const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
lock: Io.RwLock = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

/// Stores `value` under `key`, taking ownership of `value`, which must have
/// been allocated with the store's allocator. On error, ownership of `value`
/// remains with the caller.
pub fn put(s: *Store, io: Io, key: []const u8, value: []u8) (Allocator.Error || Io.Cancelable)!PutResult {
    try s.lock.lock(io);
    defer s.lock.unlock(io);

    const gop = try s.map.getOrPut(s.gpa, key);
    if (gop.found_existing) {
        s.gpa.free(gop.value_ptr.*);
        gop.value_ptr.* = value;
        return .replaced;
    }
    gop.key_ptr.* = s.gpa.dupe(u8, key) catch |err| {
        s.map.removeByPtr(gop.key_ptr);
        return err;
    };
    gop.value_ptr.* = value;
    return .created;
}

/// Returns a copy of the value stored under `key`, allocated with `gpa`,
/// or `null` if the key is absent.
pub fn get(s: *Store, io: Io, gpa: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try s.lock.lockShared(io);
    defer s.lock.unlockShared(io);

    const value = s.map.get(key) orelse return null;
    return try gpa.dupe(u8, value);
}

/// Removes `key`. Returns whether it was present.
pub fn remove(s: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    try s.lock.lock(io);
    defer s.lock.unlock(io);

    const entry = s.map.fetchRemove(key) orelse return false;
    s.gpa.free(entry.key);
    s.gpa.free(entry.value);
    return true;
}

/// Returns every key, sorted ascending, as a JSON array allocated with `gpa`.
pub fn keysJson(s: *Store, io: Io, gpa: Allocator) (Allocator.Error || Io.Cancelable)![]u8 {
    try s.lock.lockShared(io);
    defer s.lock.unlockShared(io);

    const keys = try gpa.alloc([]const u8, s.map.count());
    defer gpa.free(keys);
    var it = s.map.keyIterator();
    for (keys) |*k| k.* = it.next().?.*;
    std.mem.sortUnstable([]const u8, keys, {}, lessThan);

    var out: Io.Writer.Allocating = .init(gpa);
    errdefer out.deinit();
    const w = &out.writer;
    w.writeByte('[') catch return error.OutOfMemory;
    for (keys, 0..) |key, i| {
        if (i != 0) w.writeByte(',') catch return error.OutOfMemory;
        // Keys are restricted to [A-Za-z0-9_-], so they never need escaping.
        w.print("\"{s}\"", .{key}) catch return error.OutOfMemory;
    }
    w.writeByte(']') catch return error.OutOfMemory;
    return try out.toOwnedSlice();
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

test "put, get, replace, remove" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try testing.expectEqual(PutResult.created, try store.put(io, "a", try testing.allocator.dupe(u8, "hello")));
    try testing.expectEqual(PutResult.replaced, try store.put(io, "a", try testing.allocator.dupe(u8, "world")));

    const value = (try store.get(io, testing.allocator, "a")).?;
    defer testing.allocator.free(value);
    try testing.expectEqualStrings("world", value);

    try testing.expect(try store.remove(io, "a"));
    try testing.expect(!try store.remove(io, "a"));
    try testing.expectEqual(null, try store.get(io, testing.allocator, "a"));
}

test "keysJson sorts keys" {
    const io = testing.io;
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    {
        const empty = try store.keysJson(io, testing.allocator);
        defer testing.allocator.free(empty);
        try testing.expectEqualStrings("[]", empty);
    }

    for ([_][]const u8{ "b", "a", "_", "C", "a-1" }) |key| {
        _ = try store.put(io, key, try testing.allocator.alloc(u8, 0));
    }
    const json = try store.keysJson(io, testing.allocator);
    defer testing.allocator.free(json);
    try testing.expectEqualStrings("[\"C\",\"_\",\"a\",\"a-1\",\"b\"]", json);
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: app <port>
//! Listens on 127.0.0.1:<port> and serves until killed.

const std = @import("std");
const Io = std.Io;
const net = Io.net;

const Store = @import("Store.zig");
const Connection = @import("Connection.zig");

const log = std.log.scoped(.kvhttp);

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    if (args.len != 2) {
        log.err("usage: app <port>", .{});
        std.process.exit(2);
    }
    const port = std.fmt.parseInt(u16, args[1], 10) catch {
        log.err("invalid port: {s}", .{args[1]});
        std.process.exit(2);
    };

    var store: Store = .init(gpa);
    defer store.deinit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var server = try address.listen(io, .{ .kernel_backlog = 1024, .reuse_address = true });
    defer server.deinit(io);

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.Canceled => return,
            // Transient conditions (aborted handshakes, descriptor or memory
            // exhaustion) must not bring the server down.
            else => {
                log.warn("accept failed: {t}", .{err});
                continue;
            },
        };
        connections.concurrent(io, Connection.handle, .{ &store, io, gpa, stream }) catch |err| {
            log.warn("serving connection inline: {t}", .{err});
            Connection.handle(&store, io, gpa, stream);
        };
    }
}

test {
    _ = Store;
    _ = Connection;
    _ = @import("route.zig");
}

//! Maps a request method and path to an action, independent of any I/O.

const std = @import("std");
const http = std.http;

pub const max_key_len = 64;

pub const Action = union(enum) {
    health,
    list_keys,
    get_value: []const u8,
    put_value: []const u8,
    delete_value: []const u8,
    /// Respond with this status and an empty body.
    status: http.Status,
};

/// `method` is `null` for request methods unknown to `std.http.Method`;
/// such requests are treated like any other unsupported method.
/// Returned key slices point into `target`.
pub fn resolve(method: ?http.Method, target: []const u8) Action {
    // Request paths are not expected to carry a query string, but ignore one
    // if present so it cannot leak into the key.
    const path = target[0 .. std.mem.findScalar(u8, target, '?') orelse target.len];

    if (std.mem.eql(u8, path, "/health")) {
        return if (method == .GET) .health else .{ .status = .method_not_allowed };
    }
    if (std.mem.eql(u8, path, "/kv")) {
        return if (method == .GET) .list_keys else .{ .status = .method_not_allowed };
    }
    const prefix = "/kv/";
    if (std.mem.startsWith(u8, path, prefix)) {
        const key = path[prefix.len..];
        if (!isValidKey(key)) return .{ .status = .bad_request };
        return switch (method orelse return .{ .status = .method_not_allowed }) {
            .GET => .{ .get_value = key },
            .PUT => .{ .put_value = key },
            .DELETE => .{ .delete_value = key },
            else => .{ .status = .method_not_allowed },
        };
    }
    return .{ .status = .not_found };
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("a/b"));
    try testing.expect(!isValidKey("%41"));
    try testing.expect(!isValidKey("caf\xc3\xa9"));
}

test resolve {
    try testing.expectEqual(Action.health, resolve(.GET, "/health"));
    try testing.expectEqual(Action{ .status = .method_not_allowed }, resolve(.POST, "/health"));
    try testing.expectEqual(Action{ .status = .method_not_allowed }, resolve(null, "/health"));
    try testing.expectEqual(Action.list_keys, resolve(.GET, "/kv"));
    try testing.expectEqual(Action{ .status = .method_not_allowed }, resolve(.DELETE, "/kv"));
    try testing.expectEqualStrings("a", resolve(.GET, "/kv/a").get_value);
    try testing.expectEqualStrings("a", resolve(.PUT, "/kv/a").put_value);
    try testing.expectEqualStrings("a", resolve(.DELETE, "/kv/a").delete_value);
    try testing.expectEqual(Action{ .status = .method_not_allowed }, resolve(.PATCH, "/kv/a"));
    try testing.expectEqual(Action{ .status = .method_not_allowed }, resolve(null, "/kv/a"));
    try testing.expectEqual(Action{ .status = .bad_request }, resolve(.GET, "/kv/"));
    try testing.expectEqual(Action{ .status = .bad_request }, resolve(.PATCH, "/kv/a/b"));
    try testing.expectEqual(Action{ .status = .bad_request }, resolve(.GET, "/kv/bad.key"));
    try testing.expectEqual(Action{ .status = .not_found }, resolve(.GET, "/nope"));
    try testing.expectEqual(Action{ .status = .not_found }, resolve(.GET, "/"));
    try testing.expectEqual(Action{ .status = .not_found }, resolve(.GET, "/kvx"));
    try testing.expectEqual(Action{ .status = .not_found }, resolve(.GET, "/health/"));
}
